package com.tuap.backend.auth;
import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.tuap.backend.dominio.entidades.PendingSocialAuth; import com.tuap.backend.persistencia.PendingSocialAuthDAO;
@Service public class PendingSocialAuthService {private final PendingSocialAuthDAO dao;private final SecureRandom random=new SecureRandom();private final Clock clock;public PendingSocialAuthService(PendingSocialAuthDAO d){this(d,Clock.systemUTC());} PendingSocialAuthService(PendingSocialAuthDAO d,Clock c){dao=d;clock=c;} public String issue(VerifiedGoogleIdentity i){byte[] b=new byte[32];random.nextBytes(b);String t=Base64.getUrlEncoder().withoutPadding().encodeToString(b);Instant n=clock.instant();dao.save(new PendingSocialAuth(hash(t),AuthProvider.GOOGLE,i.subject(),i.email(),i.name(),n.plus(Duration.ofMinutes(15)),n));return t;} @Transactional public PendingSocialAuth consume(String token){PendingSocialAuth p=dao.findByTokenHash(hash(token)).orElseThrow(InvalidGoogleTokenException::new);Instant n=clock.instant();if(p.getProvider()!=AuthProvider.GOOGLE||p.getConsumedAt()!=null||!p.getExpiresAt().isAfter(n))throw new InvalidGoogleTokenException();p.consume(n);return dao.save(p);} private String hash(String t){if(t==null||t.isBlank())throw new InvalidGoogleTokenException();try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(t.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
